//! The reference random source of `pinc-sim`: `CPython`'s `random` module and the reference seed derivation, checked
//! bit for bit against vectors produced by `CPython` (`data/reference_rng.txt`, generated by
//! `scripts/gen_reference_rng.py`). Covers the generator, every method the reference harness calls, the seed
//! derivation through Python's `repr`, and the logarithm behind `expovariate`.
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing,
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss,
    clippy::cast_possible_wrap,
    clippy::too_many_lines
)]

use pinc_sim::reference::{Py, PyRandom, RefRng, blake2b_128, digest32, parse_loss_salt, seed};
use pinc_sim::{Random, Stream};

const VECTORS: &str = include_str!("data/reference_rng.txt");

fn lines(kind: &str) -> impl Iterator<Item = Vec<&'static str>> + '_ {
    VECTORS
        .lines()
        .map(|l| l.split(' ').collect::<Vec<_>>())
        .filter(move |f| f[0] == kind)
}

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap())
        .collect()
}

fn fbits(s: &str) -> f64 {
    f64::from_bits(u64::from_le_bytes(unhex(s).try_into().unwrap()))
}

fn rng(s: &str) -> PyRandom {
    PyRandom::from_seed(s.parse::<u128>().unwrap())
}

fn hexs(b: &[u8]) -> String {
    use std::fmt::Write;
    b.iter().fold(String::new(), |mut s, x| {
        let _ = write!(s, "{x:02x}");
        s
    })
}

/// The digest the generator script uses: blake2b-128 over the 8-byte little-endian bits of every value.
fn digest_f(v: impl IntoIterator<Item = f64>) -> String {
    let mut buf = Vec::new();
    for x in v {
        buf.extend_from_slice(&x.to_bits().to_le_bytes());
    }
    hexs(&blake2b_128(&buf))
}

fn digest_u(v: impl IntoIterator<Item = u64>) -> String {
    let mut buf = Vec::new();
    for x in v {
        buf.extend_from_slice(&x.to_le_bytes());
    }
    hexs(&blake2b_128(&buf))
}

fn nums<T: std::str::FromStr>(s: &str) -> Vec<T>
where
    T::Err: std::fmt::Debug,
{
    s.split(',')
        .filter(|x| !x.is_empty())
        .map(|x| x.parse().unwrap())
        .collect()
}

/// Parses the type-tagged values of a `derive` line.
enum Owned {
    None,
    Bool(bool),
    Int(i128),
    Float(f64),
    Str(String),
    Bytes(Vec<u8>),
}

fn parse_spec(tokens: &[&str]) -> Vec<Owned> {
    tokens
        .iter()
        .map(|t| {
            let (tag, v) = t.split_once(':').unwrap();
            match tag {
                "n" => Owned::None,
                "b" => Owned::Bool(v == "1"),
                "i" => Owned::Int(v.parse().unwrap()),
                "f" => Owned::Float(fbits(v)),
                "s" => Owned::Str(String::from_utf8(unhex(v)).unwrap()),
                "y" => Owned::Bytes(unhex(v)),
                _ => panic!("tag {tag}"),
            }
        })
        .collect()
}

fn borrow(o: &[Owned]) -> Vec<Py<'_>> {
    o.iter()
        .map(|x| match x {
            Owned::None => Py::None,
            Owned::Bool(b) => Py::Bool(*b),
            Owned::Int(i) => Py::Int(*i),
            Owned::Float(f) => Py::Float(*f),
            Owned::Str(s) => Py::Str(s),
            Owned::Bytes(b) => Py::Bytes(b),
        })
        .collect()
}

#[test]
fn vectors_were_made_by_cpython() {
    let v = lines("python").next().unwrap();
    assert!(v[1].starts_with("3."), "{v:?}");
}

#[test]
fn random_matches_ten_thousand_draws_per_seed() {
    let mut seeds = 0;
    for f in lines("random") {
        let mut r = rng(f[1]);
        let vals: Vec<f64> = (0..f[2].parse().unwrap()).map(|_| r.random()).collect();
        assert_eq!(digest_f(vals.iter().copied()), f[3], "seed {}", f[1]);
        for (i, h) in f[4].split(',').enumerate() {
            assert_eq!(vals[i].to_bits(), fbits(h).to_bits(), "seed {} draw {i}", f[1]);
        }
        seeds += 1;
    }
    assert!(seeds >= 15);
}

#[test]
fn getrandbits_matches_for_every_width() {
    for f in lines("bits") {
        // The generator script draws the widths one after another from one stream, so replay the earlier widths.
        let (mut r, k) = (rng(f[1]), f[2].parse::<u32>().unwrap());
        for w in [1u32, 7, 8, 31, 32, 33, 53, 64, 100, 127, 128] {
            let got: Vec<u128> = (0..12).map(|_| r.getrandbits(w)).collect();
            if w == k {
                assert_eq!(got, nums::<u128>(f[3]), "seed {} k {k}", f[1]);
                break;
            }
        }
    }
}

#[test]
fn randbelow_matches_across_bit_widths() {
    let mut cur = (String::new(), rng("0"));
    for f in lines("below") {
        if cur.0 != f[1] {
            cur = (f[1].to_string(), rng(f[1]));
        }
        let n: u64 = f[2].parse().unwrap();
        let got: Vec<u64> = (0..12).map(|_| cur.1.randbelow(n)).collect();
        assert_eq!(got, nums::<u64>(f[3]), "seed {} n {n}", f[1]);
    }
}

#[test]
fn randint_randrange_choice_shuffle_sample_follow_cpython() {
    // The `range` lines continue the stream of the `randint` lines of their seed.
    let mut cur = (String::new(), rng("0"));
    for f in VECTORS.lines().map(|l| l.split(' ').collect::<Vec<_>>()) {
        if !matches!(f[0], "randint" | "range") {
            continue;
        }
        if cur.0 != f[1] {
            cur = (f[1].to_string(), rng(f[1]));
        }
        let (a, b): (i64, i64) = (f[2].parse().unwrap(), f[3].parse().unwrap());
        let (got, want): (Vec<i64>, Vec<i64>) = if f[0] == "randint" {
            ((0..12).map(|_| cur.1.randint(a, b)).collect(), nums(f[4]))
        } else {
            ((0..12).map(|_| cur.1.randrange(a, b)).collect(), nums(f[4]))
        };
        assert_eq!(got, want, "{} seed {} {a} {b}", f[0], f[1]);
    }
    let mut cur = (String::new(), rng("0"));
    for f in lines("choice") {
        if cur.0 != f[1] {
            cur = (f[1].to_string(), rng(f[1]));
        }
        let n: usize = f[2].parse().unwrap();
        let got: Vec<usize> = (0..12).map(|_| cur.1.choice_index(n).unwrap()).collect();
        assert_eq!(got, nums::<usize>(f[3]), "choice seed {} n {n}", f[1]);
    }
    assert_eq!(rng("1").choice_index(0), None);
    let mut cur = (String::new(), rng("0"));
    for f in lines("shuffle") {
        if cur.0 != f[1] {
            cur = (f[1].to_string(), rng(f[1]));
        }
        let n: usize = f[2].parse().unwrap();
        let mut x: Vec<usize> = (0..n).collect();
        cur.1.shuffle(&mut x);
        if n <= 100 {
            assert_eq!(x, nums::<usize>(f[3]), "shuffle seed {} n {n}", f[1]);
        } else {
            assert_eq!(
                digest_u(x.iter().map(|v| *v as u64)),
                f[3],
                "shuffle seed {} n {n}",
                f[1]
            );
        }
    }
    let mut cur = (String::new(), rng("0"));
    for f in lines("sample") {
        if cur.0 != f[1] {
            cur = (f[1].to_string(), rng(f[1]));
        }
        let (n, k): (usize, usize) = (f[2].parse().unwrap(), f[3].parse().unwrap());
        let got = cur.1.sample_indices(n, k).unwrap();
        assert_eq!(
            got,
            nums::<usize>(f.get(4).copied().unwrap_or("")),
            "sample seed {} n {n} k {k}",
            f[1]
        );
    }
    assert!(rng("1").sample_indices(3, 4).is_none());
}

#[test]
fn uniform_and_expovariate_match_bit_for_bit() {
    let mut cur = (String::new(), rng("0"));
    let mut count = 0;
    for f in lines("uniform") {
        if cur.0 != f[1] {
            cur = (f[1].to_string(), rng(f[1]));
        }
        let (a, b, n) = (fbits(f[2]), fbits(f[3]), f[4].parse::<usize>().unwrap());
        let v: Vec<f64> = (0..n).map(|_| cur.1.uniform(a, b)).collect();
        assert_eq!(digest_f(v.iter().copied()), f[5], "uniform seed {} {a} {b}", f[1]);
        for (i, h) in f[6].split(',').enumerate() {
            assert_eq!(v[i].to_bits(), fbits(h).to_bits());
        }
        count += 1;
    }
    assert!(count >= 30);
    let mut cur = (String::new(), rng("0"));
    for f in lines("expo") {
        if cur.0 != f[1] {
            cur = (f[1].to_string(), rng(f[1]));
        }
        let (lam, n) = (fbits(f[2]), f[3].parse::<usize>().unwrap());
        let v: Vec<f64> = (0..n).map(|_| cur.1.expovariate(lam)).collect();
        assert_eq!(
            digest_f(v.iter().copied()),
            f[4],
            "expovariate seed {} lambd {lam}",
            f[1]
        );
        for (i, h) in f[5].split(',').enumerate() {
            assert_eq!(v[i].to_bits(), fbits(h).to_bits());
        }
    }
}

#[test]
fn bytes_and_mixed_sequences_stay_in_step() {
    for f in lines("bytes8") {
        let mut r = rng(f[1]);
        let mut rr = RefRng::python(f[1].parse().unwrap_or(0));
        let got: Vec<u8> = (0..100).map(|_| (r.next_u32() >> 24) as u8).collect();
        assert_eq!(hexs(&got), f[2], "seed {}", f[1]);
        if f[1].parse::<u64>().is_ok() {
            let mut buf = [0u8; 100];
            rr.fill(&mut buf);
            assert_eq!(hexs(&buf), f[2]);
        }
    }
    let mut cur = (String::new(), rng("0"));
    for f in lines("bytesn") {
        if cur.0 != f[1] {
            cur = (f[1].to_string(), rng(f[1]));
        }
        assert_eq!(
            hexs(&cur.1.getrandbytes(f[2].parse().unwrap())),
            f[3],
            "seed {} n {}",
            f[1],
            f[2]
        );
    }
    for f in lines("mixed") {
        let mut r = rng(f[1]);
        let mut acc = Vec::new();
        for i in 0..5000 {
            acc.push(match i % 8 {
                0 => r.random().to_bits(),
                1 => r.getrandbits(8) as u64,
                2 => r.randbelow(1000),
                3 => r.randbelow(3),
                4 => r.expovariate(0.5).to_bits(),
                5 => r.uniform(10.0, 20.0).to_bits(),
                6 => r.randint(5, 50) as u64,
                _ => r.choice_index(97).unwrap() as u64,
            });
        }
        // Floats and integers are both hashed as their 8-byte little-endian bits, as the generator script does.
        let buf: Vec<u8> = acc.iter().flat_map(|v| v.to_le_bytes()).collect();
        assert_eq!(hexs(&blake2b_128(&buf)), f[2], "seed {}", f[1]);
    }
}

#[test]
fn seed_derivation_matches_python_repr() {
    let mut n = 0;
    for f in lines("derive") {
        let owned = parse_spec(&f[3..]);
        let parts = borrow(&owned);
        let repr = String::from_utf8(unhex(f[2])).unwrap();
        assert_eq!(Py::Tuple(&parts).repr(), repr, "repr of {:?}", &f[3..]);
        assert_eq!(seed(&parts), f[1].parse::<u64>().unwrap(), "seed of {repr}");
        n += 1;
    }
    assert!(n >= 40);
    for f in lines("digest32") {
        let owned = parse_spec(&f[2..]);
        assert_eq!(hexs(&digest32(&borrow(&owned))), f[1]);
    }
}

#[test]
fn nested_tuple_and_string_reprs() {
    let inner = [Py::Int(1), Py::Str("a")];
    assert_eq!(Py::Tuple(&[Py::Tuple(&inner), Py::Tuple(&[])]).repr(), "((1, 'a'), ())");
    assert_eq!(Py::Tuple(&[Py::Tuple(&inner[..1])]).repr(), "((1,),)");
}

#[test]
fn streams_are_seeded_as_the_reference_seeds_them() {
    let s = 90_211u64;
    let tag = |t: &str, i: i128| seed(&[Py::Int(i128::from(s)), Py::Str(t), Py::Int(i)]);
    let cases = [
        (Stream::LanUp(3), tag("ge-up", 3)),
        (Stream::LanDown(3), tag("ge-down", 3)),
        (Stream::Nat(5), tag("nat", 5)),
    ];
    for (st, py_seed) in cases {
        let mut a = <RefRng as Random>::derive(s, st);
        let mut b = RefRng::python(py_seed);
        assert_eq!(a.random().to_bits(), b.random().to_bits());
    }
    // Different streams of one run draw different numbers.
    let mut u = <RefRng as Random>::derive(s, Stream::LanUp(0));
    let mut d = <RefRng as Random>::derive(s, Stream::LanDown(0));
    assert_ne!(u.random().to_bits(), d.random().to_bits());
}

#[test]
fn rust_ln_matches_cpython_log_on_every_vector() {
    let mut r = rng("2024");
    let f = lines("log").next().unwrap();
    assert_eq!(f[1], "unit");
    let v: Vec<f64> = (0..200_000).map(|_| (1.0 - r.random()).ln()).collect();
    assert_eq!(digest_f(v), f[3]);
    for f in lines("log").skip(1) {
        if f[1] == "scaled" {
            let k: i32 = f[2].parse().unwrap();
            let scale: f64 = format!("1e{k}").parse().unwrap();
            let mut r = PyRandom::from_seed((k + 1000) as u128);
            let v: Vec<f64> = (0..20_000).map(|_| (r.random() * scale + 5e-324).ln()).collect();
            assert_eq!(digest_f(v), f[4], "scale 1e{k}");
        } else {
            let mut r = rng("77");
            let v: Vec<f64> = (0..100_000).map(|_| (1.0 + (r.random() - 0.5) * 1e-6).ln()).collect();
            assert_eq!(digest_f(v), f[3], "near 1");
        }
    }
}

/// The first three draws of a stream, as bits.
fn draws(run_seed: u64, stream: Stream, salt: u64) -> [u64; 3] {
    let mut r = RefRng::derive_salted(run_seed, stream, salt);
    [(); 3].map(|()| r.random().to_bits())
}

const RUN: u64 = 86018;
const PIN_UP: [u64; 3] = [0x3fd3_cf90_e73a_21a8, 0x3fea_8f0e_152c_fcac, 0x3fe2_cc60_61ea_9611];
const PIN_DOWN: [u64; 3] = [0x3fa3_6d28_5e52_9ac0, 0x3faf_b7d5_5f91_5c10, 0x3fdf_5604_3ac9_9454];

/// The default realization of the link loss never moves: these values were drawn before the switch existed, and salt 0
/// (the variable unset or `0`) must give them again. `derive` reads the switch from the environment, which is
/// `parse_loss_salt` over `PINC_SUITE_LOSS_SALT`; both are covered here, the wrapper that reads the variable is not.
#[test]
fn the_default_realization_of_the_lan_loss_is_pinned() {
    assert_eq!(draws(RUN, Stream::LanUp(0), 0), PIN_UP);
    assert_eq!(draws(RUN, Stream::LanDown(0), 0), PIN_DOWN);
    assert_eq!(parse_loss_salt(None), Ok(0));
    assert_eq!(parse_loss_salt(Some("0")), Ok(0));
}

#[test]
fn another_realization_gives_other_lan_streams_the_same_on_a_second_call() {
    for st in [Stream::LanUp(0), Stream::LanUp(3), Stream::LanDown(0)] {
        let (d, k1, k2) = (draws(RUN, st, 0), draws(RUN, st, 1), draws(RUN, st, 2));
        assert_ne!(d, k1, "{st:?}");
        assert_ne!(d, k2, "{st:?}");
        assert_ne!(k1, k2, "{st:?}");
        assert_eq!(k1, draws(RUN, st, 1), "{st:?}");
        assert_eq!(k2, draws(RUN, st, 2), "{st:?}");
    }
}

#[test]
fn the_streams_that_are_not_a_lan_loss_are_the_same_for_every_realization() {
    for st in [
        Stream::Nat(0),
        Stream::Link { from: 1, to: 2 },
        Stream::Flood(0),
        Stream::Adversary,
    ] {
        assert_eq!(draws(RUN, st, 0), draws(RUN, st, 1), "{st:?}");
        assert_eq!(draws(RUN, st, 0), draws(RUN, st, 2), "{st:?}");
    }
}

#[test]
fn the_loss_switch_parses_a_whole_number_and_refuses_the_rest() {
    assert_eq!(parse_loss_salt(Some("7")), Ok(7));
    assert_eq!(parse_loss_salt(Some(" 3 ")), Ok(3));
    for bad in ["", "x", "-1", "1.5", "0x1"] {
        let e = parse_loss_salt(Some(bad)).unwrap_err();
        assert!(e.contains("PINC_SUITE_LOSS_SALT takes a whole number"), "{bad:?}: {e}");
    }
}
